 import unittest
from candidate import string_xor

class TestStringXOR(unittest.TestCase):
    def test_string_xor_normalcase(self):
        self.assertEqual(string_xor('010', '110'), '100')

    def test_string_xor_left_padding(self):
        self.assertEqual(string_xor('1', '10'), '0')
        self.assertEqual(string_xor('10', '1'), '0')
        self.assertEqual(string_xor('10', '10'), '0')

    def test_string_xor_right_padding(self):
        self.assertEqual(string_xor('01', '11'), '10')
        self.assertEqual(string_xor('11', '01'), '10')
        self.assertEqual(string_xor('11', '11'), '0')

    def test_string_xor_same_string(self):
        self.assertEqual(string_xor('00', '00'), '00')
        self.assertEqual(string_xor('11', '11'), '0')

    def test_string_xor_empty_strings(self):
        self.assertEqual(string_xor('', ''), '')

    def test_string_xor_one_string(self):
        self.assertEqual(string_xor('0', ''), '0')
        self.assertEqual(string_xor('', '0'), '0')
        self.assertEqual(string_xor('1', ''), '1')
        self.assertEqual(string_xor('', '1'), '1')

    def test_string_xor_non_binary(self):
        self.assertRaises(ValueError, string_xor, 'abc', 'def')

    def test_string_xor_non_string(self):
        self.assertRaises(TypeError, string_xor, 1, 2)

if __name__ == '__main__':
    unittest.main()
